// The sounds the activities can play. Both were generated by scripts/make-audio.mjs and carry
// no third-party rights (public/audio/README.md). To use other recordings, change a `src` line:
// this is the only place the paths are written.

export interface Sound {
  id: string;
  label: string;
  src: string;
}

export const SOUNDS: Sound[] = [
  { id: "warm-pad", label: "A warm, soft chord", src: "/audio/warm-pad.wav" },
  { id: "low-drone", label: "A calm, low hum", src: "/audio/low-drone.wav" },
];

export const DEFAULT_SOUND = "warm-pad";
/** Wind down the evening always uses the calm, low one. */
export const EVENING_SOUND = "low-drone";

export function soundById(id: string | undefined | null): Sound | undefined {
  return SOUNDS.find((s) => s.id === id);
}
